#pragma once

#include "CoreMinimal.h"
#include "NativeGameplayTags.h"

/** The native Gameplay Tags the plugin declares: quest categories and the built-in event kinds. Games may add more. */
namespace QuestTags
{
	/** Category: story quests. Default limit of one active at a time. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Category_Story);

	/** Category: bounties, usually generated by the bounty board. Default limit of three active. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Category_Bounty);

	/** Category: timed quests. Default limit of one active. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Category_Timed);

	/** Event: something was destroyed. Its subject tags say what. Counted by Destroy objectives. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Event_TargetDestroyed);

	/** Event: an item was collected. Collect objectives re-read the inventory on it. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Event_ItemCollected);

	/** Event: a place was reached. Its context id says which. Completes Visit objectives. */
	QUESTFRAMEWORK_API UE_DECLARE_GAMEPLAY_TAG_EXTERN(Event_LocationReached);
}
